def receive(self, amount: int) -> int:
    if amount < 0:
        raise ValueError("negative damage")
    hp_dealt = 0
    if self.shield > 0:
        shield_taken = min(self.shield, amount)
        self.shield -= shield_taken
        amount -= shield_taken
    if amount > 0:
        hp_dealt = min(self.hp, amount)
        self.hp -= hp_dealt
        self.alive = self.hp > 0
    return hp_dealt

